using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using System.Web.Script.Serialization;using XHLLauncher;
class AlignGameplay {
 static int Main(string[] args){try{return Run(args);}catch(Exception ex){try{File.WriteAllText(Path.Combine(args[1],"Gameplay-alignment-error.txt"),ex.ToString());}catch{}Console.WriteLine("Alignment stopped: "+ex.Message);return 1;}} static int Run(string[] args){string app=args[0],output=args[1];bool apply=args.Length==3&&args[2]=="--apply";LauncherSettings settings;using(var f=File.OpenRead(Path.Combine(app,"Manager Data","settings.xml")))settings=(LauncherSettings)new System.Xml.Serialization.XmlSerializer(typeof(LauncherSettings)).Deserialize(f);string root=settings.ServerRoot,path=Path.Combine(root,"enshrouded_server.json");var data=Maintenance.Config(root);var proposals=ConfigAlignment.Proposed(data);var fields=ConfigurationDocument.Flatten(data);var changes=proposals.Select(p=>new{path=p.Key,before=fields.First(f=>f.Path==p.Key).Value,after=p.Value}).ToArray();File.WriteAllText(Path.Combine(output,"Gameplay-range-alignment.json"),new JavaScriptSerializer().Serialize(new{applied=false,changes=changes}));foreach(var c in changes)Console.WriteLine(c.path+": "+c.before+" => "+c.after);if(!apply||changes.Length==0)return 0;
  string expected=InstallationAudit.Hash(path);var preflight=ServerLifecycle.CheckInstallation(root);if(!preflight.Success)throw new IOException(preflight.Message);var runtime=new ExistingServerRuntime(root,settings);var lifecycle=new ServerLifecycle(runtime,()=>ServerLifecycle.CheckInstallation(root));bool wasRunning=runtime.IsRunning;if(wasRunning){var cfg=ConfigReader.Read(root);var info=ServerQuery.Read("127.0.0.1",cfg.QueryPort,1500);if(info.Players!=0)throw new IOException("Players are online; alignment postponed.");var result=lifecycle.Execute("Stop");Console.WriteLine(result.Message);if(!result.Success||runtime.IsRunning)throw new IOException("Graceful shutdown did not complete; configuration not modified.");}
  string backupRoot=string.IsNullOrWhiteSpace(settings.BackupRoot)?Path.Combine(app,"World-Backups"):settings.BackupRoot;var backup=SaveBackup.Create(root,backupRoot,false);Console.WriteLine(backup.Message);if(!backup.Success)throw new IOException("Offline backup failed; no config change applied. Server remains stopped for review.");if(InstallationAudit.Hash(path)!=expected)throw new IOException("Configuration changed after preview; no modification made. Server remains stopped for review.");foreach(var p in proposals){var f=fields.First(x=>x.Path==p.Key);f.Set(ConfigurationDocument.ConvertValue(f,p.Value));}var save=Maintenance.SaveConfiguration(root,new JavaScriptSerializer().Serialize(data),expected);Console.WriteLine(save.Message);if(!save.Success)throw new IOException("Configuration save failed; server remains stopped for review.");var after=Maintenance.Config(root);var expectedFields=ConfigurationDocument.Flatten(data);var diffs=ConfigurationDocument.Flatten(after).Where(f=>new JavaScriptSerializer().Serialize(f.Value)!=new JavaScriptSerializer().Serialize(expectedFields.First(x=>x.Path==f.Path).Value)).ToArray();if(diffs.Length>0)throw new IOException("Unexpected post-save differences; review retained config backup.");File.WriteAllText(Path.Combine(output,"Gameplay-range-alignment.json"),new JavaScriptSerializer().Serialize(new{applied=true,changes=changes,offlineBackup=backup.Message,configResult=save.Message}));
  if(wasRunning){var start=lifecycle.Execute("Start");Console.WriteLine(start.Message);if(!start.Success)return 2;DateTime deadline=DateTime.UtcNow.AddMinutes(4);while(DateTime.UtcNow<deadline){Thread.Sleep(1000);if(!runtime.IsRunning)continue;try{var cfg=ConfigReader.Read(root);var info=ServerQuery.Read("127.0.0.1",cfg.QueryPort,1000);Console.WriteLine("Game query confirmed: "+info.Name+", "+info.Players+" / "+info.Capacity);return 0;}catch{}}Console.WriteLine("Startup requested but readiness is unconfirmed. No repeat start attempted.");return 3;}return 0;
 }
}


